function requireMember(chatId: string, userId: string, res: Response) {
  const chat = getChatById(chatId);
  if (!chat) {
    res.status(404).json({ error: 'not_found' });
    return null;
  }
  if (!chat.memberIds.includes(userId)) {
    res.status(403).json({ error: 'forbidden' });
    return null;
  }
  return chat;
}

function broadcastNewMessage(
  chatId: string,
  message: ReturnType<typeof createMessage>,
  senderId: string,
): void {
  emitToChat(chatId, 'message.new', { message });
  const chat = getChatById(chatId);
  if (!chat) return;
  for (const memberId of chat.memberIds) {
    if (memberId === senderId) continue;
    if (!isUserOnline(memberId)) continue;
    const updated = updateMessageStatus(message.id, 'delivered');
