        messageId: updated.id,
        chatId,
        status: updated.status,
      });
      emitToUser(senderId, 'message.status', {
        messageId: updated.id,
        chatId,
        status: updated.status,
      });
    }
  }
  emitToChat(chatId, 'chat.updated', { chatId });
}

