async function handleTextMessage(req: Request, res: Response): Promise<void> {
  const { user } = asAuthed(req);
  const chatId = req.params.chatId as string;
  if (!requireMember(chatId, user.id, res)) return;

  const body = req.body as { type?: unknown; text?: unknown };
  if (body.type !== 'text' || typeof body.text !== 'string') {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  const text = body.text;
  if (text.length < 1 || text.length > 4000) {
    res.status(400).json({ error: 'invalid' });
    return;
  }

  const message = createMessage({
    chatId,
    senderId: user.id,
    type: 'text',
    text,
    audioId: null,
    audioDurationMs: null,
    status: 'sent',
  });
  touchChat(chatId);
  broadcastNewMessage(chatId, message, user.id);
  res.status(201).json(message);
}

async function handleAudioMessage(req: Request, res: Response): Promise<void> {
  const { user } = asAuthed(req);
  const chatId = req.params.chatId as string;
  if (!requireMember(chatId, user.id, res)) return;

  const type = typeof req.body?.type === 'string' ? req.body.type : undefined;
  const durationRaw = req.body?.durationMs;
  const durationMs = typeof durationRaw === 'string' ? Number(durationRaw) : Number(durationRaw);
  const file = req.file;

  if (
    type !== 'audio' ||
    !file ||
    !Number.isFinite(durationMs) ||
    durationMs < 1 ||
    durationMs > 60000 ||
    file.size <= 0 ||
    file.size > 5 * 1024 * 1024
  ) {
    res.status(400).json({ error: 'invalid_audio' });
    return;
  }

  const mime = (file.mimetype || '').toLowerCase();
  const okMime =
    AUDIO_MIMES.has(mime) ||
    mime.startsWith('audio/') &&
      (mime.includes('mp4') ||
        mime.includes('m4a') ||
        mime.includes('aac') ||
        mime.includes('webm'));
  if (!okMime) {
    res.status(400).json({ error: 'invalid_audio' });
    return;
  }

  const id = randomUUID();
  await mkdir(uploadsDir, { recursive: true });
  const dest = path.join(uploadsDir, id);
  const { Readable } = await import('node:stream');
  await pipeline(Readable.from(file.buffer), createWriteStream(dest));

  const media = saveMedia({
    id,
    path: dest,
    mime: file.mimetype || 'audio/mp4',
    size: file.size,
  });

  const message = createMessage({
    chatId,
    senderId: user.id,
    type: 'audio',
    text: null,
    audioId: media.id,
    audioDurationMs: Math.floor(durationMs),
    status: 'sent',
  });
  touchChat(chatId);
  broadcastNewMessage(chatId, message, user.id);
  res.status(201).json(message);
}

